steps.code:
# Now let's parse the old_songs list (already in variable `old_songs`) into a set of (title, artist) tuples for matching.
# We'll also normalize the strings for robust matching (strip, lower).

def normalize(s):
    return s.strip().lower()

old_song_tuples = set()
for line in old_songs:
    # Assume format: "Song Title - Artist Name"
    if " - " in line:
        title, artist = line.split(" - ", 1)
        old_song_tuples.add((normalize(title), normalize(artist)))

print(old_song_tuples)

