# Now, let's check if a playlist named "Archived Songs" already exists in the user's playlist library.
# If it does, we'll use its playlist_id; if not, we'll create it.
archived_playlist = None
for playlist in all_playlists:
    if playlist["title"].strip().lower() == "archived songs":
        archived_playlist = playlist
        break

if archived_playlist is None:
    create_response = apis.spotify.create_playlist(title="Archived Songs", access_token=spotify_access_token)
    print(create_response)
else:
    print({"playlist_id": archived_playlist["playlist_id"]})

