steps.code:
# The search returns a list of songs with their song_id, title, and artists.
# To accurately match, we should look for a song where the title matches (case-insensitive, ignoring whitespace) and the artist is among the artists listed.
# Let's write a function to get the song_id for each (title, artist) in old_songs.

def find_song_id(title, artist, access_token):
    query = f"{title} {artist}"
    results = apis.spotify.search_songs(access_token=access_token, query=query, page_index=0, page_limit=10)
    for song in results:
        # Match title (case-insensitive, strip whitespace)
        if song["title"].strip().lower() == title.strip().lower():
            # Check if any artist matches (case-insensitive)
            if any(a["name"].strip().lower() == artist.strip().lower() for a in song["artists"]):
                return song["song_id"]
    return None

# Now, get all song_ids to remove
old_song_ids = []
for title, artist in old_songs:
    song_id = find_song_id(title, artist, spotify_access_token)
    if song_id is not None:
        old_song_ids.append(song_id)

print(old_song_ids)  # List of song_ids to remove and archive

