steps.code:
# Let's fetch the details for all unique song_ids.
# We'll store a mapping from song_id to a string of the form "Title by Artist" for easy matching.
# We'll also store the full song details for later use.

song_id_to_info = {}
song_id_to_full = {}

for song_id in all_song_ids:
    song = apis.spotify.show_song(song_id=song_id)
    if song and "title" in song and "artists" in song and song["artists"]:
        artist_names = ", ".join(artist["name"] for artist in song["artists"])
        song_id_to_info[song_id] = f'{song["title"]} by {artist_names}'
        song_id_to_full[song_id] = song

# Let's print a few mappings to verify.
for sid in list(song_id_to_info.keys())[:5]:
    print(f"{sid}: {song_id_to_info[sid]}")

