# I can get song details by calling apis.spotify.show_song(song_id=<id>).
# Let's fetch the metadata for all unique song_ids. Since there are 56 song_ids, I'll fetch them in a loop and store the results in a dictionary keyed by song_id.

song_metadata = {}
for song_id in all_song_ids:
    song_metadata[song_id] = apis.spotify.show_song(song_id=song_id)
print(song_metadata)

# Now, let's map the song titles and artists from `songs_to_archive` to song_ids in `song_metadata`.
# We'll create a set of song_ids to archive by matching both title and artist (from the format "<title> by <artist>").

songs_to_archive_ids = set()
for entry in songs_to_archive:
    if " by " in entry:
        title, artist = entry.rsplit(" by ", 1)
        for song_id, meta in song_metadata.items():
            if meta["title"] == title and any(a["name"] == artist for a in meta["artists"]):
                songs_to_archive_ids.add(int(song_id))
                break

print(songs_to_archive_ids)

# For each (title, artist) pair, I will search using the query "<title> <artist>" and try to match the artist name exactly in the results.
# I'll collect the song_ids for all songs to archive.
# Let's do this for all songs in songs_to_archive_list.

songs_to_archive_ids = []
for title, artist in songs_to_archive_list:
    query = f"{title} {artist}"
    results = apis.spotify.search_songs(
        access_token=spotify_access_token,
        query=query,
        page_limit=5
    )
    # Find the first result with an exact artist match
    found_id = None
    for song in results:
        for song_artist in song.get("artists", []):
            if song_artist["name"].lower() == artist.lower():
                found_id = song["song_id"]
                break
        if found_id:
            break
    if found_id:
        songs_to_archive_ids.append(found_id)

print(songs_to_archive_ids)

