# Let's check if a playlist named "Archived Playlist Songs" already exists in the user's playlist library.
archived_playlist = None
for playlist in playlists:
    if playlist["title"] == "Archived Playlist Songs":
        archived_playlist = playlist
        break

if archived_playlist is None:
    # Create the playlist if it doesn't exist
    resp = apis.spotify.create_playlist(title="Archived Playlist Songs", access_token=spotify_access_token)
    print(resp)
else:
    print({"playlist_id": archived_playlist["playlist_id"], "title": archived_playlist["title"]})

